228	     * Return the Pet with the given name, or null if none found for this Owner.
229	     *
230	     * @param name to test
231	     * @return true if pet name is already in use
232	     */
233	    public Pet getPet(String name) {
234	        return getPet(name, false);
235	    }
236	
237	    /**
238	     * Return the Pet with the given name, or null if none found for this Owner.
239	     *
240	     * @param name to test
241	     * @return true if pet name is already in use
242	     */
243	    public Pet getPet(String name, boolean ignoreNew) {
244	        name = name.toLowerCase();
245	        for (Pet pet : getPetsInternal()) {
246	            if (!ignoreNew || !pet.isNew()) {
247	                String compName = pet.getName();
248	                compName = compName.toLowerCase();
249	                if (compName.equals(name)) {
250	                    return pet;
251	                }
252	            }
253	        }
254	        return null;
255	    }
256	
257	    public Pet getPet(Integer petId) {
258	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
259	    }
