261	    @Override
262	    public String toString() {
263	        return new ToStringCreator(this)
264	
265	            .append("id", this.getId())
266	            .append("new", this.isNew())
267	            .append("lastName", this.getLastName())
268	            .append("firstName", this.getFirstName())
269	            .append("address", this.address)
270	            .append("city", this.city)
271	            .append("telephone", this.telephone)
272	            .toString();
273	    }
274	}
