22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
24	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
25	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
26	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) + ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
27	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
28	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
29	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
35	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
36	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
37	     */
38	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
39	        java.time.LocalDate birthDate = owner.getBirthDate();
40	        java.time.LocalDate asOf = owner.getRegistrationDate();
41	        if (birthDate == null || asOf == null) {
42	            return null;
43	        }
44	        int years = java.time.Period.between(birthDate, asOf).getYears();
45	        if (years < 18) {
46	            return OwnerDto.AgeBandEnum.MINOR;
47	        }
48	        if (years < 65) {
49	            return OwnerDto.AgeBandEnum.ADULT;
50	        }
51	        return OwnerDto.AgeBandEnum.SENIOR;
52	    }
53	
54	    Owner toOwner(OwnerDto ownerDto);
55	
56	    @Mapping(target = "id", ignore = true)
57	    @Mapping(target = "pets", ignore = true)
58	    Owner toOwner(OwnerFieldsDto ownerDto);
59	
60	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
61	
62	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
63	
64	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
65	        OwnerPageDto ownerPageDto = new OwnerPageDto();
66	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
67	        ownerPageDto.setPage(ownerPage.getNumber());
68	        ownerPageDto.setSize(ownerPage.getSize());
69	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
70	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
71	        return ownerPageDto;
72	    }
73	}
